SINA_SMART["bacterio1-mycoplasma"] = {"lecture":"bacterio1-mycoplasma","title":"Mycoplasma","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"bacterio1-mycoplasma:e0","text":"Mollicutes: no cell wall, sterol membrane, smallest free-living prokaryotes.","topic":"Characteristics","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycoplasma:e1","text":"Not Gram-stainable; pleomorphic; special media (SP-4, PPLO, Hayflick).","topic":"Characteristics","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycoplasma:e2","text":"M. pneumoniae: strict human respiratory pathogen; droplets.","topic":"Characteristics","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycoplasma:e3","text":"Extracellular, tightly adherent; cytadherence organelle, CARDS toxin, H₂O₂.","topic":"Pathogenicity and virulence","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycoplasma:e4","text":"Atypical 'walking' pneumonia; cold agglutinins.","topic":"Clinical manifestations","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycoplasma:e5","text":"M. hominis: PID, pyelonephritis, postpartum fever; Ureaplasma: NGU.","topic":"Clinical manifestations","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycoplasma:e6","text":"PCR = gold standard; culture slow and rare; serology on paired sera.","topic":"Diagnosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycoplasma:e7","text":"Natural resistance to β-lactams.","topic":"Treatment","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycoplasma:e8","text":"Treat with macrolides, tetracyclines or fluoroquinolones.","topic":"Treatment","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"115pata":"a","yn3dyk":"a","yk7m7p":"a","pj2sux":"a","19evy0c":"a","1jxukse":"a","fuztd1":"a","1dhwpac":"a","1kgw6mn":"a","6g9qcj":"a","10v7uku":"a","dwsmh5":"a","1pet333":"a","rw3wqd":"x","15455so":"x"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":2},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"bacterio1-mycoplasma:e0":{"s":0,"u":["Mollicutes: no cell wall, sterol membrane, smallest free-living prokaryotes.","Mycoplasmas belong to the class Mollicutes (Latin mollis , soft; cutis , skin), defined by the absence of a rigid cell wall .","Their membrane contains sterols (cholesterol) taken from the host, so they are fragile outside it."],"dp":[]},"bacterio1-mycoplasma:e1":{"s":0,"u":["Not Gram-stainable; pleomorphic; special media (SP-4, PPLO, Hayflick).","Non-motile, non-sporing, facultatively anaerobic; they grow at 37 °C, pH 7.4-7.8, in reduced oxygen with CO₂, on special rich media ( SP-4, PPLO, modified Hayflick ), and are frequent contaminants of cell cultures.","They are coccoid or filamentous and pleomorphic, do not fit the Gram classification, and are the smallest prokaryotes capable of autonomous multiplication (0.3-0.85 µm)."],"dp":[]},"bacterio1-mycoplasma:e2":{"s":0,"u":["M. pneumoniae: strict human respiratory pathogen; droplets.","Species: M. pneumoniae , a strict human respiratory pathogen; M. genitalium , M. hominis and Ureaplasma urealyticum , urogenital colonisers and opportunists.","Transmission: droplets, sexual contact, vertical."],"dp":[]},"bacterio1-mycoplasma:e3":{"s":1,"u":["Extracellular, tightly adherent; cytadherence organelle, CARDS toxin, H₂O₂.","Virulence factors: an attachment (cytadherence) organelle with adhesins, variable surface proteins (antigenic variation), the CARDS toxin (ADP-ribosylating; inflammation and ciliary damage), hydrogen peroxide production and biofilm formation.","Mycoplasmas are host-dependent, colonise mucosal surfaces and stay extracellular but tightly adherent to epithelium, often as asymptomatic colonisers."],"dp":[]},"bacterio1-mycoplasma:e4":{"s":2,"u":["Atypical 'walking' pneumonia; cold agglutinins.","M. pneumoniae : tracheobronchitis, sore throat, ear inflammation and atypical ('walking') pneumonia ; the lecture ranks it the second cause of community-acquired pneumonia after pneumococcus (the Chlamydia lecture ranks C. pneumoniae third).","It can induce cold agglutinins (autoantibodies against red cells) and occasional systemic complications."],"dp":[]},"bacterio1-mycoplasma:e5":{"s":2,"u":["M. hominis: PID, pyelonephritis, postpartum fever; Ureaplasma: NGU.","M. hominis : pelvic inflammatory disease, pyelonephritis, spontaneous abortion, postpartum fever.","Ureaplasma urealyticum : non-gonococcal urethritis in men, PID."],"dp":[]},"bacterio1-mycoplasma:e6":{"s":3,"u":["PCR = gold standard; culture slow and rare; serology on paired sera.","Direct : PCR is the gold standard on throat swabs or nasopharyngeal aspirates (no transport medium needed); rapid real-time platforms give results in about 4 hours.","Indirect : serology (ELISA IgM, IgG, IgA; complement fixation; agglutination) on paired sera 2-4 weeks apart; IgM suggests recent infection; limits: delayed positivity, cross-reactions, poor value in immunocompromised patients."],"dp":[]},"bacterio1-mycoplasma:e7":{"s":4,"u":["Natural resistance to β-lactams.","Natural resistance to β-lactams and all drugs acting on peptidoglycan synthesis (no wall)."],"dp":[]},"bacterio1-mycoplasma:e8":{"s":4,"u":["Treat with macrolides, tetracyclines or fluoroquinolones.","Effective: macrolides and related MLSK drugs, tetracyclines and fluoroquinolones .","Macrolides are usual in children (tetracyclines and fluoroquinolones are avoided); macrolide resistance has emerged in some regions."],"dp":[]}},"meta":{"115pata":{"a":"recall","vg":"bacterio1-mycoplasma:e0/recall/1"},"yn3dyk":{"a":"recall","vg":"bacterio1-mycoplasma:e0/recall/2"},"yk7m7p":{"a":"recall","vg":"bacterio1-mycoplasma:e0/recall/3"},"pj2sux":{"a":"recall","vg":"bacterio1-mycoplasma:e7/recall/1"},"19evy0c":{"a":"recall","vg":"bacterio1-mycoplasma:e4/recall/1"},"1jxukse":{"a":"recall","vg":"bacterio1-mycoplasma:e4/recall/2"},"fuztd1":{"a":"recall","vg":"bacterio1-mycoplasma:e5/recall/1"},"1dhwpac":{"a":"recall","vg":"bacterio1-mycoplasma:e5/recall/2"},"1kgw6mn":{"a":"recall","vg":"bacterio1-mycoplasma:e6/recall/1"},"6g9qcj":{"a":"recall","vg":"bacterio1-mycoplasma:e6/recall/2"},"10v7uku":{"a":"recall","vg":"bacterio1-mycoplasma:e3/recall/1"},"dwsmh5":{"a":"recall","vg":"bacterio1-mycoplasma:e3/recall/2"},"1pet333":{"a":"recall","vg":"bacterio1-mycoplasma:e8/recall/1"}},"explRev":"b4c63465f9d0"};
